// Valide l'input et prépare l'extraction.
// Accepte file_url / b2_file_key (téléchargement) OU file_data base64 (aligné OCR).
// Capture mime_type + filename : mime_type sert à poser le Content-Type de l'appel Tika
// (sans quoi Tika peut retomber sur EmptyParser → extraction vide silencieuse).
const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const fileUrl = body.file_url || ctx.file_url || null;
const b2FileKey = body.b2_file_key || ctx.b2_file_key || null;
const b2BucketUrl = body.b2_bucket_url || ctx.b2_bucket_url || 'https://f005.backblazeb2.com/file/azy-storage';

let fileData = body.file_data || ctx.file_data || null;
if (fileData && fileData.includes(',')) fileData = fileData.split(',')[1];  // retire le préfixe data:...;base64,

const mimeType = body.mime_type || ctx.mime_type || null;
const filename = body.filename || ctx.filename || 'document';

let url = fileUrl;
if (!url && b2FileKey) url = `${b2BucketUrl}/${b2FileKey}`;

if (!url && !fileData) {
  return [{ json: { valid: false, error: { code: 400, message: 'file_url, b2_file_key ou file_data requis' } } }];
}

return [{ json: {
  valid: true,
  source: fileData ? 'base64' : 'url',
  file_url: url,
  file_data: fileData,
  mime_type: mimeType,
  filename,
} }];

// Parse la réponse XHTML de Tika (Accept: text/html) en détail PAR PAGE.
// Tika délimite les pages PDF par <div class="page">. Les formats NON paginés
// (DOCX, HTML, e-mail…) n'en produisent pas → traités comme une page unique.
// Le par-page alimente l'aiguillage OCR (azy.daily#123/#147) : une page sous le
// seuil = pas de couche texte exploitable.
const SEUIL = 50;   // caractères/page en deçà desquels une page est jugée sans couche texte

const raw = String(($input.first().json.data) || '');

function stripTags(s) {
  return s.replace(/<[^>]+>/g, ' ')
          .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
          .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
          .replace(/\s+/g, ' ').trim();
}

// Découpe sur le marqueur de page — robuste aux <p> imbriqués (un regex de div
// équilibrée casserait). parts[0] = en-tête avant la 1re page, ignoré.
const parts = raw.split('<div class="page">');
let pages;
if (parts.length > 1) {
  pages = parts.slice(1).map((chunk, i) => {
    const text = stripTags(chunk);
    return { index: i, text, chars: text.length };
  });
} else {
  const text = stripTags(raw);
  pages = [{ index: 0, text, chars: text.length }];
}

const fullText = pages.map(p => p.text).filter(Boolean).join('\n\n');
const pagesVides = pages.filter(p => p.chars < SEUIL).map(p => p.index);

// Aucun texte nulle part : document image/scanné, ou Content-Type mal posé (EmptyParser).
// On ne renvoie PAS d'erreur — c'est une information exploitable, pas un échec.
return [{ json: {
  success: true,
  engine: 'tika',
  format: 'plain',
  text: fullText,
  char_count: fullText.length,
  page_count: pages.length,
  pages,                                   // [{index, text, chars}]
  pages_vides: pagesVides,                 // pages sous le seuil — [] si tout va bien
  ocr_recommande: pagesVides.length > 0,   // indice, pas verdict : l'appelant décide
  seuil_car_page: SEUIL,
  // Déclaré dès la V1 (rétro-compat), peuplé en V1.1 via /unpack (azy.daily#149).
  // Vide ici : extraction texte seule. Les images embarquées viennent d'un 2ᵉ appel.
  assets: [],
} }];

// Chemin base64 : reconstruit le binaire sans téléchargement (aligné sur le pattern OCR).
const src = $input.first().json;
const buf = Buffer.from(src.file_data, 'base64');
return [{
  json: { mime_type: src.mime_type, filename: src.filename },
  binary: { data: await this.helpers.prepareBinaryData(buf, src.filename, src.mime_type || 'application/octet-stream') },
}];
